import React, { useRef } from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, spring, interpolate, random } from '../remotionShim';
{/* Start Google Fonts Loader */ }
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700;800`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */ }



export type FloatingText3DProps = Record<string, any>;

const FloatingText3D: React.FC<FloatingText3DProps> = ({
  backgroundColor = "#0f0518", // Dark purple/black base
  transparentBackground = false,
  durationInSeconds = 5,
  textTitle = "THE STABLECOIN REVOLUTION",
  subtitleText = "2024 Changed Everything",
  primaryColor = "#ffffff",
  glowColor = "#d946ef", // Neon Magenta/Pink
  fontSize = 70,
  xPosition = 50,
  yPosition = 50,
  rotationY = 0,
  rotationX = 0,
  shadowOpacity = 0.6,
  delayFrames = 10,
  displayIcon = true,
  // Lower Third Defaults - Cleared to focus on main title card request
  lowerThirdTextInitial = "",
  lowerThirdTextFinal = "",
  lowerThirdFontSize = 40,
  lowerThirdOffsetBottom = 15,
  lowerThirdSwitchDelay = 60,
  lowerThirdPrimaryColor = "#ffffff",
  lowerThirdSecondaryColor = "#00ffff",
}) => {
  useFontLoader(["Montserrat"]);

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Safely calculate background color with a subtle purple gradient
  const backgroundStyle = transparentBackground
    ? { backgroundColor: "transparent" }
    : { background: `radial-gradient(circle at center, #2a0a3d 0%, ${backgroundColor} 100%)` };

  // --- Main Title Animation ---
  const spr = spring({
    frame: frame - delayFrames,
    fps,
    config: {
      damping: 12,
      stiffness: 120,
      mass: 0.8,
    },
    durationInFrames: 20,
  });

  // Neon Flicker Effect
  const flicker = interpolate(
    frame - delayFrames,
    [0, 5, 10, 15, 20, 25, 40],
    [0, 0.2, 0.1, 0.8, 0.2, 1, 1],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  // Subtle Glow Pulse
  const pulse = Math.sin(frame / 15) * 0.1 + 0.95;

  const textShadow = `
    0 0 15px ${glowColor},
    0 0 30px ${glowColor}, 
    0 0 50px ${glowColor},
    2px 5px 10px rgba(0,0,0, ${shadowOpacity})
  `;

  // Soft glow around the container
  const boxGlow = `
    0 0 20px ${glowColor}50, 
    0 0 40px ${glowColor}30, 
    inset 0 0 30px ${glowColor}10
  `;

  const transformStyle = {
    transform: `
      perspective(1000px)
      translate(-50%, -50%)
      rotateY(${rotationY}deg)
      rotateX(${rotationX}deg)
      scale(${spr})
    `,
  };

  // --- Background Particles ---
  const particles = React.useMemo(() => {
    return new Array(20).fill(0).map((_, i) => {
      const seed = i * 432.1;
      const x = (random(seed) * 100);
      const size = random(seed + 1) * 3 + 1;
      const speed = random(seed + 2) * 0.3 + 0.1;
      return { x, size, speed, seed };
    });
  }, []);

  // Icon Animation (Floating)
  const iconFloat = Math.sin(frame / 20) * 10;
  const iconRotate = Math.sin(frame / 40) * 5;

  // --- Lower Third Animation (Preserved logic) ---
  const lowerThirdEntranceOpacity = interpolate(
    frame,
    [delayFrames + 10, delayFrames + 25],
    [0, 1],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  const lowerThirdEntranceY = interpolate(
    frame,
    [delayFrames + 10, delayFrames + 25],
    [20, 0],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  const switchStartFrame = delayFrames + 10 + lowerThirdSwitchDelay;
  const switchDuration = 15;

  const initialTextOpacity = interpolate(
    frame,
    [switchStartFrame, switchStartFrame + switchDuration],
    [1, 0],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  const finalTextOpacity = interpolate(
    frame,
    [switchStartFrame, switchStartFrame + switchDuration],
    [0, 1],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  return (
    <AbsoluteFill
      style={{
        ...backgroundStyle,
        fontFamily: "Montserrat",
        overflow: "hidden",
        transition: "none",
      }}
    >
      {/* Background Particles/Rays */}
      {!transparentBackground && particles.map((p, i) => {
        const floatY = 110 - ((frame * p.speed + (p.seed * 20)) % 120);
        // Fade in/out at edges
        const opacity = interpolate(floatY, [0, 20, 90, 110], [0, 0.4, 0.4, 0]);

        return (
          <div
            key={i}
            style={{
              position: "absolute",
              left: `${p.x}%`,
              top: `${floatY}%`,
              width: p.size,
              height: p.size * 5, // Stretched for "light ray" effect
              borderRadius: "4px",
              background: `linear-gradient(to bottom, transparent, ${glowColor}40, transparent)`,
              opacity: opacity * 0.5,
              filter: "blur(2px)",
            }}
          />
        );
      })}

      {/* Main 3D Floating Title Container */}
      <div
        style={{
          position: "absolute",
          left: `${xPosition}%`,
          top: `${yPosition}%`,
          width: width * 0.8,
          display: "flex",
          justifyContent: "center",
          alignItems: "center",
          zIndex: 10,
          ...transformStyle,
        }}
      >
        {/* Glassmorphism Frame */}
        <div
          style={{
            position: "relative",
            border: `1px solid ${glowColor}60`,
            borderRadius: 40,
            padding: "50px 80px",
            backgroundColor: "rgba(15, 5, 24, 0.6)", // Darker semi-transparent backing
            boxShadow: boxGlow,
            opacity: flicker,
            display: "flex",
            flexDirection: "column",
            justifyContent: "center",
            alignItems: "center",
            textAlign: "center",
            backdropFilter: "blur(12px)",
          }}
        >
          {/* Main Title */}
          <h1
            style={{
              margin: 0,
              fontSize: fontSize,
              fontWeight: 800,
              lineHeight: 1.1,
              color: primaryColor,
              textShadow: textShadow,
              textTransform: "uppercase",
              letterSpacing: "0.02em",
              opacity: pulse,
            }}
          >
            {textTitle}
          </h1>

          {/* Subtitle (New Element) */}
          {subtitleText && (
            <h2
              style={{
                marginTop: 20,
                marginBottom: 0,
                fontSize: fontSize * 0.35,
                fontWeight: 500,
                color: "#e0e0e0",
                letterSpacing: "0.1em",
                textShadow: `0 2px 4px rgba(0,0,0,0.8)`,
                opacity: 0.9,
              }}
            >
              {subtitleText}
            </h2>
          )}

          {/* Floating Icon (New Element) */}
          {displayIcon && (
            <div
              style={{
                position: "absolute",
                top: -30,
                right: -30,
                width: fontSize * 1.5,
                height: fontSize * 1.5,
                transform: `translateY(${iconFloat}px) rotate(${15 + iconRotate}deg)`,
                filter: `drop-shadow(0 0 15px ${glowColor})`,
              }}
            >
              <svg viewBox="0 0 100 100" fill="none" xmlns="http://www.w3.org/2000/svg">
                <circle cx="50" cy="50" r="45" stroke={glowColor} strokeWidth="4" fill="rgba(0,0,0,0.5)" />
                <path
                  d="M50 25V75 M35 35H60L35 65H65"
                  stroke={primaryColor}
                  strokeWidth="6"
                  strokeLinecap="round"
                  strokeLinejoin="round"
                />
              </svg>
            </div>
          )}
        </div>
      </div>

      {/* Legacy Lower Third Overlay (Only renders if text is present) */}
      {(lowerThirdTextInitial || lowerThirdTextFinal) && (
        <div
          style={{
            position: "absolute",
            bottom: `${lowerThirdOffsetBottom}%`,
            left: "50%",
            transform: `translateX(-50%) translateY(${lowerThirdEntranceY}px)`,
            opacity: lowerThirdEntranceOpacity,
            textAlign: "center",
            width: "100%",
            display: "flex",
            justifyContent: "center",
            alignItems: "center",
            zIndex: 5,
          }}
        >
          <div style={{ position: "relative", height: lowerThirdFontSize * 1.5, width: width * 0.8 }}>

            <h2
              style={{
                position: "absolute",
                top: 0,
                left: 0,
                right: 0,
                margin: 0,
                fontSize: lowerThirdFontSize,
                fontWeight: 700,
                color: lowerThirdPrimaryColor,
                textDecoration: "line-through",
                textDecorationThickness: "3px",
                opacity: initialTextOpacity,
                textShadow: "0px 2px 4px rgba(0,0,0,0.6)",
              }}
            >
              {lowerThirdTextInitial}
            </h2>

            <h2
              style={{
                position: "absolute",
                top: 0,
                left: 0,
                right: 0,
                margin: 0,
                fontSize: lowerThirdFontSize,
                fontWeight: 700,
                color: lowerThirdSecondaryColor,
                opacity: finalTextOpacity,
                textShadow: `0 0 10px ${lowerThirdSecondaryColor}, 0px 2px 4px rgba(0,0,0,0.6)`,
              }}
            >
              {lowerThirdTextFinal}
            </h2>
          </div>
        </div>
      )}
    </AbsoluteFill>
  );
};

export default FloatingText3D;